import java.io.*;
import java.util.*;

public class Solution {
    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = null;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    System.out.println(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            try {
                if (st == null || !st.hasMoreTokens()) {
                    st = new StringTokenizer(br.readLine());
                }
            } catch (IOException e) {
                System.out.println(e);
            }
            return st.nextToken("\n");
        }
    }

    static final long MOD = 998244353L;
    static final int MAX_SIZE = 200005;
    static long[] factorials = new long[MAX_SIZE];

    static long modPow(long base, long exp, long mod) {
        long result = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long nCr(int n, int r) {
        if (r > n) return 0L;
        return factorials[n] * modPow(factorials[r], MOD - 2, MOD) % MOD * modPow(factorials[n - r], MOD - 2, MOD) % MOD;
    }

    static long compute(int n, int k) {
        long total = 0;
        for (int i = 0; i <= n - k; i++) {
            long term = nCr(n - k, i) * modPow(n - k - i, n, MOD) % MOD;
            if (i % 2 == 0) total = (total + term) % MOD;
            else total = (total - term + MOD) % MOD;
        }
        return total;
    }

    public static void main(String[] args) {
        InputReader in = new InputReader();
        int t = 1;
        // t = in.nextInt();
        for (int q = 0; q < t; q++) {
            long n = in.nextLong();
            long k = in.nextLong();
            factorials[0] = 1;
            for (long i = 1; i <= n; i++) {
                factorials[(int) i] = factorials[(int) (i - 1)] * i % MOD;
            }
            if (k >= n) {
                System.out.println(0);
            } else if (k == 0) {
                System.out.println(factorials[(int) n]);
            } else {
                long result = 2 * nCr((int) n, (int) (n - k)) * compute((int) n, (int) k) % MOD;
                System.out.println(result);
            }
        }
    }
}
