    std::istream& in;
    std::string token;
    std::stringstream ss;

    InputReader(std::istream& input_stream) : in(input_stream) {}

    std::string next() {
        while (!(ss >> token)) {
            if (!(in >> token)) {
                return "";
            }
            ss.clear();
            ss.str(token);
        }
        return token;
    }

    int nextInt() {
